package com.gmail.manhle240406.project.community;
import android.os.Bundle;
import android.content.Intent;
import android.view.*;
import android.widget.*;
import androidx.activity.EdgeToEdge;
import androidx.appcompat.app.AppCompatActivity;
import androidx.lifecycle.ViewModelProvider;
import com.google.android.material.dialog.MaterialAlertDialogBuilder;
import com.google.android.material.textfield.TextInputEditText;
import com.gmail.manhle240406.project.AniloveApplication;
import com.gmail.manhle240406.project.R;
import com.google.firebase.firestore.*;
import java.util.*;
import static com.gmail.manhle240406.project.community.SocialViews.*;
import static com.gmail.manhle240406.project.community.SocialRepository.*;

public final class SocialDetailActivity extends AppCompatActivity {
    private String consumedSocial,consumedReport;private AuthorLookup authors;private String authorLabel;
    private DailyViewModel model;private LinearLayout col,comments;private TextView story,status;private TextInputEditText reply;private androidx.appcompat.app.AlertDialog dialog;private ListenerRegistration detailListener,commentListener;
    @Override public void onCreate(Bundle state){super.onCreate(state);EdgeToEdge.enable(this);model=new ViewModelProvider(this).get(DailyViewModel.class);if(model.lost){finish();return;}authors=new AuthorLookup(model.sessions);if(model.postId==null)model.identify(getIntent().getStringExtra("post"));LinearLayout outer=column(this);install(this,outer);insets(outer);ScrollView scroll=new ScrollView(this);outer.addView(scroll);col=column(this);scroll.addView(col);col.addView(button(this,getString(R.string.social_close),this::finish));story=text(this,"",false);col.addView(story);status=text(this,"",false);status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);col.addView(status);
        col.addView(button(this,getString(R.string.social_menu),this::postMenu));col.addView(button(this,getString(R.string.social_like),()->{boolean desired=model.like==null||!Boolean.TRUE.equals(model.like.get("active"));if(model.projection==null&&desired)return;model.send(new SocialCommand("set_like",model.postId,null,number(model.projection,"contentVersion"),0,number(model.like,"likeVersion"),map("active",desired),UUID.randomUUID().toString()));}));
        reply=field(this,col,getString(R.string.social_comment),3);reply.setText(model.body);reply.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void afterTextChanged(android.text.Editable e){}public void onTextChanged(CharSequence s,int start,int before,int count){model.body=s.toString();}});col.addView(primaryButton(this,getString(R.string.social_send_comment),()->{if(!text(model.body.trim(),500,2000)){reply.setError(getString(R.string.social_comment_invalid));return;}model.send(new SocialCommand("add_comment",model.postId,UUID.randomUUID().toString(),number(model.projection,"contentVersion"),0,0,map("body",model.body.trim()),UUID.randomUUID().toString()));}));comments=column(this);col.addView(comments);col.addView(button(this,getString(R.string.social_more_comments),()->loadComments(true)));col.addView(button(this,getString(R.string.social_retry),model::retry));col.addView(button(this,getString(R.string.social_reconcile),model::reconcile));model.changes.observe(this,x->render());load();privateView(outer);if(model.editingCommentId!=null)outer.post(this::editComment);}
    private void load(){model.read("communityFeed/"+model.postId,p->{model.projection=p!=null&&SocialSchema.feed(p,model.postId)?p:null;if(model.projection!=null){authorLabel=getString(R.string.social_member);authors.get((String)p.get("authorUid")).addOnSuccessListener(alias->{if(!model.current()||isDestroyed())return;authorLabel=alias==null?getString(R.string.social_member):(String)alias.get("displayName");model.changed();});loadComments(false);model.read("communityCounts/"+model.postId,c->model.count=c);}else{model.rows.clear();comments.removeAllViews();}model.read("communityPosts/"+model.postId+"/likes/"+model.ticket.uid,c->model.like=c);});}
    private void loadComments(boolean next){if(model.lost||model.projection==null||next&&model.cursor==null)return;model.commentStart=next?model.cursor:null;attachComments();}
    private void attachComments(){if(commentListener!=null)commentListener.remove();if(!model.current()||model.projection==null)return;commentListener=model.social.commentPage(model.postId,model.commentStart,(snapshot,error)->{if(!model.current()||isDestroyed())return;if(error!=null){model.rows.clear();model.notice="unavailable";model.changed();return;}if(snapshot==null||snapshot.getMetadata().isFromCache())return;List<DocumentSnapshot> docs=snapshot.getDocuments();model.rows=new ArrayList<>();for(DocumentSnapshot d:docs)if(SocialSchema.comment(d.getData(),model.postId,d.getId())){model.rows.add(d);if(model.ticket.uid.equals(d.get("authorUid")))model.ownComments.put(d.getId(),d.getData());}while(model.ownComments.size()>20)model.ownComments.remove(model.ownComments.keySet().iterator().next());model.cursor=docs.size()==20?docs.get(19):null;model.read("communityCounts/"+model.postId,c->model.count=c);model.changed();});}
    private void postMenu(){if(model.projection==null)return;boolean own=model.ticket.uid.equals(model.projection.get("authorUid"));String[] choices=own?new String[]{getString(R.string.social_edit),getString(R.string.community_hide),getString(R.string.social_delete),getString(R.string.report_title)}:new String[]{getString(R.string.report_title)};dialog=new MaterialAlertDialogBuilder(this).setItems(choices,(d,w)->{if(!own||w==3){ReportSheet.target("post",model.postId,null,number(model.projection,"contentVersion"),null).show(getSupportFragmentManager(),"report");return;}if(w==0){startActivity(new Intent(this,SocialComposerActivity.class).putExtra("post",model.postId));return;}model.read("communityPosts/"+model.postId,r->{model.root=r;if(r==null||isDestroyed()||isFinishing())return;Runnable action=()->model.send(new SocialCommand(w==1?"hide":"archive",model.postId,null,number(r,"contentVersion"),number(r,"controlVersion"),0,Collections.emptyMap(),UUID.randomUUID().toString()));if(w==2)dialog=new MaterialAlertDialogBuilder(this).setMessage(R.string.social_delete_help).setPositiveButton(R.string.social_delete,(a,b)->action.run()).setNegativeButton(android.R.string.cancel,null).show();else action.run();});}).show();}
    private void commentMenu(DocumentSnapshot row){String cid=row.getId();boolean own=model.ticket.uid.equals(row.getString("authorUid"));dialog=new MaterialAlertDialogBuilder(this).setItems(own?new String[]{getString(R.string.social_edit),getString(R.string.social_withdraw),getString(R.string.report_title)}:new String[]{getString(R.string.report_title)},(d,w)->{if(!own||w==2){ReportSheet.target("comment",cid,model.postId,number(row.getData(),"commentVersion"),null).show(getSupportFragmentManager(),"report");return;}if(w==1){model.send(new SocialCommand("withdraw_comment",model.postId,cid,number(row.getData(),"sourceContentVersion"),0,number(row.getData(),"commentVersion"),Collections.emptyMap(),UUID.randomUUID().toString()));return;}model.editingCommentId=cid;model.editingCommentVersion=number(row.getData(),"commentVersion");model.commentEditText=row.getString("body");editComment();}).show();}
    private void editComment(){if(model.editingCommentId==null||isDestroyed())return;LinearLayout fields=column(this);TextInputEditText edit=field(this,fields,getString(R.string.social_comment),3);edit.setText(model.commentEditText);edit.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void afterTextChanged(android.text.Editable e){}public void onTextChanged(CharSequence s,int a,int b,int c){model.commentEditText=s.toString();}});dialog=new MaterialAlertDialogBuilder(this).setTitle(R.string.social_edit).setView(fields).setPositiveButton(R.string.social_send_comment,null).setNegativeButton(android.R.string.cancel,(d,w)->{model.editingCommentId=null;model.commentEditText="";}).create();dialog.setOnShowListener(v->dialog.getButton(androidx.appcompat.app.AlertDialog.BUTTON_POSITIVE).setOnClickListener(button->{String candidate=model.commentEditText.trim();if(!text(candidate,500,2000)){edit.setError(getString(R.string.social_comment_invalid));edit.requestFocus();return;}model.send(new SocialCommand("edit_comment",model.postId,model.editingCommentId,number(model.projection,"contentVersion"),0,model.editingCommentVersion,map("body",candidate),UUID.randomUUID().toString()));model.editingCommentId=null;model.commentEditText="";dialog.dismiss();}));dialog.show();}
    private void render(){if(model.lost){if(dialog!=null)dialog.dismiss();finish();return;}if(model.lastCommittedReport!=null&&!model.lastCommittedReport.equals(consumedReport)){consumedReport=model.lastCommittedReport;com.google.android.material.snackbar.Snackbar.make(col,R.string.report_received,com.google.android.material.snackbar.Snackbar.LENGTH_LONG).setAction(R.string.report_mine,v->startActivity(new Intent(this,MyReportsActivity.class))).show();}story.setText(model.projection==null?getString(R.string.social_removed):(authorLabel==null?getString(R.string.social_member):authorLabel)+" · "+getString(R.string.social_audience)+(model.projection.get("editedAt")==null?"":" · "+getString(R.string.social_edited))+"\n\n"+model.projection.get("body"));status.setText(DailyCopy.notice(this,model.notice)+(model.count==null?"":" · "+getString(R.string.social_likes,number(model.count,"likeCount"))));reply.setEnabled(!model.busy&&model.projection!=null);if(!reply.getText().toString().equals(model.body))reply.setText(model.body);comments.removeAllViews();if(model.projection==null)for(Map.Entry<String,Map<String,Object>> entry:model.ownComments.entrySet())comments.addView(button(this,getString(R.string.social_withdraw),()->model.read("communityPosts/"+model.postId+"/comments/"+entry.getKey(),c->{if(c==null||!"visible".equals(c.get("state")))return;model.send(new SocialCommand("withdraw_comment",model.postId,entry.getKey(),number(c,"sourceContentVersion"),0,number(c,"commentVersion"),Collections.emptyMap(),UUID.randomUUID().toString()));})));for(DocumentSnapshot row:model.rows){comments.addView(text(this,getString(R.string.social_member)+"\n"+row.getString("body")+(number(row.getData(),"sourceContentVersion")<number(model.projection,"contentVersion")?"\n"+getString(R.string.social_source_edited):""),false));comments.addView(button(this,getString(R.string.social_menu),()->commentMenu(row)));}if(model.lastCommittedSocial!=null&&!model.lastCommittedSocial.equals(consumedSocial)){consumedSocial=model.lastCommittedSocial;load();}}
    @Override protected void onStart(){super.onStart();if(model!=null&&!model.lost)detailListener=FirebaseFirestore.getInstance().document("communityFeed/"+model.postId).addSnapshotListener((d,e)->{if(!model.current())return;if(e!=null){model.projection=null;model.rows.clear();model.changed();}else if(d!=null&&!d.getMetadata().isFromCache()){boolean first=model.projection==null;model.projection=d.exists()&&SocialSchema.feed(d.getData(),model.postId)?d.getData():null;if(model.projection==null)model.rows.clear();else if(first||commentListener==null)attachComments();model.changed();}});}
    @Override protected void onStop(){if(detailListener!=null){detailListener.remove();detailListener=null;}if(commentListener!=null){commentListener.remove();commentListener=null;}super.onStop();}
    @Override protected void onDestroy(){if(dialog!=null)dialog.dismiss();if(authors!=null)authors.close();super.onDestroy();}
}
